//! bench-only arm over the incumbent's prebuilt onnxruntime 1.20.1 (CPU execution provider).
//!
//! composes `libloading` (dlopen) with bindgen's dynamic-loading `OrtLib`, generated from the
//! `onnxruntime_c_api.h` shipped in the same release tarball; nothing onnxruntime is compiled.
//! [`OrtRuntime::load`] refuses any other dylib and any other reported version before the api
//! table is requested, so the bindings' struct layout always matches the binary that runs.

// generated by bindgen from ort-headers/onnxruntime_c_api.h; regenerate with `regen_bindings`
#[allow(
    clippy::all,
    clippy::pedantic,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    dead_code,
    unsafe_op_in_unsafe_fn
)]
pub mod bindings;
mod session;
mod stats;

pub use session::EmbedSession;
pub use stats::{coefficient_of_variation, cosine, l2_normalize, max_abs_diff, mean};

use std::env;
use std::ffi::{CStr, c_char};
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use sha2::{Digest, Sha256};
use thiserror::Error;

use bindings::{OrtApi, OrtLib};

pub const DEFAULT_LIB_DIR: &str =
    "/Users/brianbruggeman/.hermes/tools/onnxruntime-osx-arm64-1.20.1/onnxruntime-osx-arm64-1.20.1/lib/";
pub const LIB_DIR_ENV: &str = "ORT_LIB_DIR";
pub const ORT_LIB_FILE: &str = "libonnxruntime.1.20.1.dylib";
pub const PINNED_SHA256: &str = "530cdb5a0de774677d369a83ec8912b0242e9769acd12d34b61412ee6ae368ae";
pub const PINNED_VERSION: &str = "1.20.1";
pub const ORT_API_VERSION: u32 = 20;

const HEX_DIGITS: &[u8; 16] = b"0123456789abcdef";

#[derive(Debug, Error)]
pub enum LoadError {
    #[error("cannot read {path}: {source}")]
    Io { path: PathBuf, source: io::Error },
    #[error("sha256 mismatch for {path}: expected {expected}, actual {actual}")]
    ShaMismatch { path: PathBuf, expected: String, actual: String },
    #[error("onnxruntime version mismatch: expected {expected}, actual {actual}")]
    VersionMismatch { expected: String, actual: String },
    #[error("cannot resolve onnxruntime from {path}: {source}")]
    Resolve { path: PathBuf, source: libloading::Error },
    #[error("OrtApiBase.GetApi missing or returned null for api version {0}")]
    NoApi(u32),
    #[error("OrtApiBase.GetVersionString missing or returned null")]
    NoVersionString,
    #[error("onnxruntime api table lacks {0}")]
    MissingFunction(&'static str),
    #[error("onnxruntime call {call} failed: {message}")]
    Ort { call: &'static str, message: String },
    #[error("path {0} contains a NUL byte")]
    BadPath(PathBuf),
    #[error("model graph shape mismatch: {0}")]
    Model(String),
}

/// what the gate observed; goes in the scoreboard's `binary_sha256` and `ort_version` columns.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GateReport {
    pub sha256: String,
    pub version: String,
}

pub struct OrtRuntime {
    // held only to keep the dylib mapped while `api` points into it
    _lib: OrtLib,
    api: *const OrtApi,
    pub report: GateReport,
}

/// `$ORT_LIB_DIR` or the default install dir.
#[must_use]
pub fn lib_dir_from_env() -> PathBuf {
    env::var_os(LIB_DIR_ENV).map_or_else(|| PathBuf::from(DEFAULT_LIB_DIR), PathBuf::from)
}

/// sha256 hex of the file's bytes.
///
/// # Errors
/// [`LoadError::Io`] when the file cannot be read.
pub fn sha256_hex(path: &Path) -> Result<String, LoadError> {
    let bytes = fs::read(path).map_err(|source| LoadError::Io { path: path.to_path_buf(), source })?;
    let digits = Sha256::digest(&bytes)
        .iter()
        .flat_map(|byte| [byte >> 4, byte & 0x0f])
        .map(|nibble| char::from(HEX_DIGITS[usize::from(nibble)]))
        .collect();
    Ok(digits)
}

/// # Errors
/// [`LoadError::ShaMismatch`] naming expected and actual.
pub fn check_sha(path: &Path, actual: &str, expected: &str) -> Result<(), LoadError> {
    if actual == expected {
        return Ok(());
    }
    Err(LoadError::ShaMismatch {
        path: path.to_path_buf(),
        expected: expected.to_owned(),
        actual: actual.to_owned(),
    })
}

/// # Errors
/// [`LoadError::VersionMismatch`] naming expected and actual.
pub fn check_version(actual: &str, expected: &str) -> Result<(), LoadError> {
    if actual == expected {
        return Ok(());
    }
    Err(LoadError::VersionMismatch { expected: expected.to_owned(), actual: actual.to_owned() })
}

/// hashes the dylib in `dir` against the pin; touches no onnxruntime symbol.
///
/// # Errors
/// [`LoadError::Io`] or [`LoadError::ShaMismatch`].
pub fn verify_sha(dir: &Path) -> Result<String, LoadError> {
    let path = dir.join(ORT_LIB_FILE);
    let sha256 = sha256_hex(&path)?;
    check_sha(&path, &sha256, PINNED_SHA256)?;
    Ok(sha256)
}

impl OrtRuntime {
    /// sha gate, then dlopen, then version gate, then the api table for [`ORT_API_VERSION`].
    ///
    /// # Errors
    /// any gate failure, or a missing library or symbol.
    pub fn load(dir: &Path) -> Result<Self, LoadError> {
        let sha256 = verify_sha(dir)?;
        let path = dir.join(ORT_LIB_FILE);
        // safety: sha256 equals the pinned release, so the bindings' layouts match this binary
        let lib = unsafe { OrtLib::new(&path) }
            .map_err(|source| LoadError::Resolve { path: path.clone(), source })?;
        // safety: OrtGetApiBase takes no arguments and returns a static table
        let base = unsafe { lib.OrtGetApiBase() };
        // safety: a non-null base points at the static OrtApiBase inside the pinned dylib
        let base = unsafe { base.as_ref() }.ok_or(LoadError::NoApi(ORT_API_VERSION))?;
        let version_fn = base.GetVersionString.ok_or(LoadError::NoVersionString)?;
        // safety: the pinned dylib returns a static NUL-terminated string
        let version_ptr: *const c_char = unsafe { version_fn() };
        if version_ptr.is_null() {
            return Err(LoadError::NoVersionString);
        }
        // safety: non-null, NUL-terminated, static
        let version = unsafe { CStr::from_ptr(version_ptr) }.to_string_lossy().into_owned();
        check_version(&version, PINNED_VERSION)?;
        let get_api = base.GetApi.ok_or(LoadError::NoApi(ORT_API_VERSION))?;
        // safety: version string equals the pin, which supports api version 20
        let api = unsafe { get_api(ORT_API_VERSION) };
        if api.is_null() {
            return Err(LoadError::NoApi(ORT_API_VERSION));
        }
        Ok(Self { _lib: lib, api, report: GateReport { sha256, version } })
    }

    pub(crate) fn api(&self) -> &OrtApi {
        // safety: non-null checked in load; the table lives as long as self._lib keeps the dylib mapped
        unsafe { &*self.api }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn pinned_dir() -> PathBuf {
        lib_dir_from_env()
    }

    #[test]
    fn gate_accepts_the_pinned_dylib() {
        let runtime = OrtRuntime::load(&pinned_dir()).expect("pinned install must pass both gates and load");
        assert_eq!(runtime.report.sha256, PINNED_SHA256);
        assert_eq!(runtime.report.version, PINNED_VERSION);
    }

    #[test]
    fn byte_altered_copy_is_rejected_with_sha_mismatch() {
        let scratch = tempfile::tempdir().expect("tempdir");
        let altered = scratch.path().join(ORT_LIB_FILE);
        let mut bytes = fs::read(pinned_dir().join(ORT_LIB_FILE)).expect("read real libonnxruntime");
        bytes[4096] ^= 0xff;
        fs::write(&altered, bytes).expect("write altered copy");
        let actual = sha256_hex(&altered).expect("hash altered copy");
        let error = check_sha(&altered, &actual, PINNED_SHA256).expect_err("altered bytes must not pass");
        assert!(matches!(&error, LoadError::ShaMismatch { expected, actual: seen, .. }
            if expected == PINNED_SHA256 && *seen == actual));
        let load_error = OrtRuntime::load(scratch.path()).err().expect("altered dir must not load");
        assert!(matches!(load_error, LoadError::ShaMismatch { .. }), "{load_error}");
    }

    #[test]
    fn unpinned_version_is_rejected() {
        let error = check_version("1.20.0", PINNED_VERSION).expect_err("1.20.0 must not pass");
        assert!(matches!(&error, LoadError::VersionMismatch { expected, actual }
            if expected == "1.20.1" && actual == "1.20.0"));
        assert!(error.to_string().contains("expected 1.20.1, actual 1.20.0"));
    }

    #[test]
    fn missing_dylib_is_an_io_error() {
        let scratch = tempfile::tempdir().expect("tempdir");
        let error = verify_sha(scratch.path()).expect_err("empty dir has no dylib");
        assert!(matches!(error, LoadError::Io { .. }), "{error}");
    }
}
